-- Yêu cầu: bảng profiles phải có ít nhất 1 user
-- Nếu chưa có user/profile, hãy đăng ký 1 tài khoản trước rồi chạy lại.

with author_profile as (
  select id
  from public.profiles
  order by created_at asc
  limit 1
),
seed_posts(title, slug, excerpt, content) as (
  values
    -- ========== REACT CHUYÊN SÂU ==========
    (
      'React Hooks: Từ useState đến useReducer',
      'react-hooks-tu-usestate-den-usereducer',
      'Hiểu rõ cách sử dụng Hooks trong React và khi nào nên dùng useReducer thay vì useState.',
      E'React Hooks là feature hữu ích giúp chúng ta sử dụng state và lifecycle mà không cần Class Component. Bài viết này sẽ đi sâu vào cách sử dụng hooks, từ useState cơ bản đến useReducer phức tạp.\n\n## useState - Quản lý state đơn giản\n\nuseState là hook phổ biến nhất. Nó nhận giá trị khởi tạo và trả về một mảng gồm state hiện tại và hàm update.\n\nVí dụ:\n```jsx\nconst [count, setCount] = useState(0);\n```\n\nĐây là cách để quản lý state trong functional component. Mỗi lần setCount được gọi, component sẽ re-render với giá trị state mới.\n\n## useEffect - Side effects trong functional component\n\nuseEffect cho phép ta thực hiện các tác vụ phụ như fetch data, subscribe event, hoặc thay đổi DOM.\n\n```jsx\nuseEffect(() => {\n  // Logic ở đây sẽ chạy sau khi component render\n  document.title = `Clicked ${count} times`;\n  return () => {\n    // Cleanup function (optional)\n  };\n}, [count]); // dependency array\n```\n\n## useReducer - Quản lý state phức tạp\n\nKhi state có logic phức tạp, useReducer là lựa chọn tốt hơn useState. Nó giống như Redux nhưng nhỏ hơn.\n\n```jsx\nconst reducer = (state, action) => {\n  switch(action.type) {\n    case ''INCREMENT'':\n      return { count: state.count + 1 };\n    case ''DECREMENT'':\n      return { count: state.count - 1 };\n    default:\n      return state;\n  }\n};\n\nconst [state, dispatch] = useReducer(reducer, { count: 0 });\n```\n\n## useContext - Tránh prop drilling\n\nuseContext giúp truy cập context mà không cần prop drilling qua nhiều component.\n\n## Kết luận\n\nCó thể sử dụng useReducer khi:\n- State có nhiều state values liên quan\n- Logic update state phức tạp\n- Muốn tối ưu hiệu năng bằng cách truyền dispatch xuống thay vì callback\n\nHãy chọn hook phù hợp với nhu cầu bài toán của bạn.'
    ),
    (
      'Performance Optimization trong React: memo, useMemo, useCallback',
      'performance-optimization-trong-react-memo-usememo-usecallback',
      'Cách tối ưu render performance bằng React.memo, useMemo và useCallback.',
      E'Khi ứng dụng React phát triển, hiệu năng render có thể trở thành vấn đề. Bài viết này hướng dẫn cách tối ưu performance bằng các kỹ thuật như memoization.\n\n## React.memo - Ngăn re-render không cần thiết\n\nReact.memo là HOC (Higher Order Component) giúp component chỉ re-render khi props thay đổi.\n\n```jsx\nconst MyComponent = React.memo(({ name, age }) => {\n  return <div>{name} - {age}</div>;\n});\n```\n\nNếu component parent re-render nhưng props không thay đổi, MyComponent sẽ không re-render lại.\n\n## useMemo - Cache giá trị tính toán\n\nuseMemo giúp cache kết quả tính toán để tránh tính lại mỗi khi render.\n\n```jsx\nconst expensiveValue = useMemo(() => {\n  return largeArray.map(item => item * 2);\n}, [largeArray]);\n```\n\nNếu dependency không thay đổi, useMemo sẽ trả về kết quả từ lần trước mà không tính lại.\n\n## useCallback - Cache function reference\n\nuseCallback tương tự useMemo nhưng cho function. Nó đảm bảo function reference không thay đổi (trừ khi dependency thay đổi).\n\n```jsx\nconst handleClick = useCallback(() => {\n  doSomething(value);\n}, [value]);\n```\n\nĐây rất hữu ích khi truyền callback xuống child component được bọc bởi React.memo.\n\n## Khi nào sử dụng?\n\n- React.memo: Child component render lại thường xuyên nhưng props ít thay đổi\n- useMemo: Tính toán tốn kém (sorting, filtering large array)\n- useCallback: Truyền callback xuống memo component hoặc sử dụng trong dependency array\n\nTuy nhiên, hãy nhớ: không phải lúc nào cũng cần optimize. Hãy profile ứng dụng trước và optimize sau khi phát hiện bottleneck!'
    ),
    (
      'Custom Hooks: Tái sử dụng logic trong React',
      'custom-hooks-tai-su-dung-logic-trong-react',
      'Tạo custom hooks để giảm code duplication và tái sử dụng logic giữa các component.',
      E'Custom hooks là cách tuyệt vời để chia sẻ logic giữa các component. Chúng là function JavaScript bắt đầu với "use" và có thể sử dụng các hooks khác.\n\n## Ví dụ: useFetch Hook\n\nHãy tạo custom hook để fetch data:\n\n```jsx\nfunction useFetch(url) {\n  const [data, setData] = useState(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState(null);\n\n  useEffect(() => {\n    fetch(url)\n      .then(res => res.json())\n      .then(data => {\n        setData(data);\n        setLoading(false);\n      })\n      .catch(err => {\n        setError(err);\n        setLoading(false);\n      });\n  }, [url]);\n\n  return { data, loading, error };\n}\n```\n\nBây giờ có thể sử dụng ở bất kỳ component nào:\n\n```jsx\nfunction UserProfile() {\n  const { data: user, loading, error } = useFetch(''/api/user'');\n  \n  if (loading) return <div>Loading...</div>;\n  if (error) return <div>Error: {error.message}</div>;\n  \n  return <div>{user.name}</div>;\n}\n```\n\n## Ví dụ: useLocalStorage Hook\n\nHook để đồng bộ state với localStorage:\n\n```jsx\nfunction useLocalStorage(key, initialValue) {\n  const [storedValue, setStoredValue] = useState(() => {\n    try {\n      const item = window.localStorage.getItem(key);\n      return item ? JSON.parse(item) : initialValue;\n    } catch (error) {\n      console.log(error);\n      return initialValue;\n    }\n  });\n\n  const setValue = (value) => {\n    try {\n      setStoredValue(value);\n      window.localStorage.setItem(key, JSON.stringify(value));\n    } catch (error) {\n      console.log(error);\n    }\n  };\n\n  return [storedValue, setValue];\n}\n```\n\n## Lợi ích của Custom Hooks\n\n1. **Code reusability**: Chia sẻ logic giữa các component\n2. **Cleaner components**: Component chỉ focus vào rendering logic\n3. **Dễ test**: Logic được tách biệt trong hook riêng\n4. **Type safety**: Dễ thêm TypeScript types\n\nKhi viết custom hooks, luôn nhớ: nó phải bắt đầu với "use" để TypeScript và linter hiểu rằng nó là một hook!'
    ),

    -- ========== TYPESCRIPT ADVANCED ==========
    (
      'TypeScript Generics: Viết code tái sử dụng được',
      'typescript-generics-viet-code-tai-su-dung-duoc',
      'Hiểu về TypeScript Generics và cách sử dụng chúng để tạo code linh hoạt và type-safe.',
      E'TypeScript Generics là tính năng mạnh mẽ cho phép viết code tái sử dụng được mà vẫn đảm bảo type safety. Generics cho phép bạn viết function, class hoặc interface hoạt động với nhiều type khác nhau.\n\n## Generic Functions\n\nBắt đầu với một ví dụ đơn giản:\n\n```typescript\nfunction identity<T>(arg: T): T {\n  return arg;\n}\n\nlet output1 = identity<string>("myString");\nlet output2 = identity<number>(123);\n```\n\nHere, T là type variable. Nó sẽ được thay thế bởi type thực tế khi function được gọi.\n\n## Generic Constraints\n\nĐôi khi bạn muốn limit generic type. Sử dụng extends:\n\n```typescript\ninterface HasLength {\n  length: number;\n}\n\nfunction loggingIdentity<T extends HasLength>(arg: T): T {\n  console.log(arg.length);\n  return arg;\n}\n\nloggingIdentity({ length: 10, value: 3 }); // OK\nloggingIdentity(3); // Error: number không có property length\n```\n\n## Generic Classes\n\n```typescript\nclass GenericQueue<T> {\n  private items: T[] = [];\n\n  enqueue(item: T) {\n    this.items.push(item);\n  }\n\n  dequeue(): T | undefined {\n    return this.items.shift();\n  }\n}\n\nconst queue = new GenericQueue<string>();\nqueue.enqueue("Hello");\nqueue.enqueue("World");\n```\n\n## Conditional Types\n\nConditional types cho phép chọn một type dựa trên điều kiện:\n\n```typescript\ntype IsString<T> = T extends string ? true : false;\n\ntype A = IsString<"hello">; // true\ntype B = IsString<42>; // false\n```\n\n## Mapped Types\n\nMapped types cho phép tạo type mới từ type cũ:\n\n```typescript\ntype ReadonlyPerson = {\n  readonly [K in keyof Person]: Person[K];\n};\n```\n\nĐây tương đương với:\n\n```typescript\ntype ReadonlyPerson = {\n  readonly name: string;\n  readonly age: number;\n};\n```\n\n## Lợi ích của Generics\n\n- **Type Safety**: Phát hiện lỗi tại compile time\n- **Code Reusability**: Viết một lần, sử dụng cho nhiều type\n- **Better IDE Support**: Autocomplete và refactoring tốt hơn\n- **Documentation**: Code tự nó là documentation'
    ),
    (
      'TypeScript Decorators và Metadata',
      'typescript-decorators-va-metadata',
      'Sử dụng Decorators để thêm metadata và tính năng vào class, method, property.',
      E'TypeScript Decorators là tính năng nâng cao cho phép annotate và modify class declaration, method, accessor, property hoặc parameter. Nó thường được dùng trong frameworks như Angular, NestJS.\n\n## Class Decorators\n\nClass decorator nhận class constructor và có thể modify nó:\n\n```typescript\nfunction sealed(constructor: Function) {\n  Object.seal(constructor);\n  Object.seal(constructor.prototype);\n}\n\n@sealed\nclass Greeter {\n  greeting: string;\n  constructor(message: string) {\n    this.greeting = message;\n  }\n  greet() {\n    return "Hello, " + this.greeting;\n  }\n}\n```\n\n## Method Decorators\n\nMethod decorator nhận 3 parameters: target (object chứa method), propertyKey (tên method), descriptor (method descriptor).\n\n```typescript\nfunction enumerable(value: boolean) {\n  return function (target: any, propertyKey: string, descriptor: PropertyDescriptor) {\n    descriptor.enumerable = value;\n  };\n}\n\nclass Greeter {\n  greeting: string;\n  constructor(message: string) {\n    this.greeting = message;\n  }\n  @enumerable(false)\n  greet() {\n    return "Hello, " + this.greeting;\n  }\n}\n```\n\n## Property Decorators\n\n```typescript\nfunction readonly(target: any, propertyKey: string) {\n  Object.defineProperty(target, propertyKey, {\n    writable: false,\n  });\n}\n\nclass Person {\n  @readonly\n  name: string = "John";\n}\n```\n\n## Metadata với Reflect\n\nĐôi khi decorators cần lưu thông tin kèm theo. TypeScript cung cấp reflect-metadata:\n\n```typescript\nimport "reflect-metadata";\n\nfunction validate(target: any, propertyKey: string, descriptor: PropertyDescriptor) {\n  Reflect.setMetadata("validation", true, target, propertyKey);\n}\n\nclass User {\n  @validate\n  email: string;\n}\n\nconst hasValidation = Reflect.getMetadata("validation", User.prototype, "email");\nconsole.log(hasValidation); // true\n```\n\n## Ứng dụng thực tế\n\nDecorators rất hữu ích cho:\n1. **ORM Libraries**: Định nghĩa schema bằng decorators (TypeORM)\n2. **API Frameworks**: Định nghĩa routes (NestJS)\n3. **Validation**: Thêm validation rules\n4. **Logging**: Tự động log method calls\n\nDecorators là experimental feature, nhớ bật "experimentalDecorators" trong tsconfig.json!'
    ),

    -- ========== DATABASE OPTIMIZATION ==========
    (
      'PostgreSQL Query Optimization: Index và EXPLAIN',
      'postgresql-query-optimization-index-va-explain',
      'Cách sử dụng INDEX, EXPLAIN ANALYZE để tối ưu query PostgreSQL.',
      E'PostgreSQL là database mạnh mẽ nhưng query chậm có thể là vấn đề lớn. Bài viết này hướng dẫn cách tối ưu query bằng index và analyze plan.\n\n## EXPLAIN ANALYZE - Xem query plan\n\nTrước tiên, hãy xem execution plan của query:\n\n```sql\nEXPLAIN ANALYZE\nSELECT * FROM posts WHERE author_id = ''123'';\n```\n\nKết quả sẽ cho biết:\n- Node type (Sequential Scan, Index Scan, Hash Join)\n- Rows estimated vs actual\n- Execution time\n\n## Indexes - Tăng tốc độ truy vấn\n\nIndex giúp database tìm kiếm dữ liệu nhanh hơn:\n\n```sql\n-- Create simple index\nCREATE INDEX idx_posts_author_id ON posts(author_id);\n\n-- After creating index\nEXPLAIN ANALYZE\nSELECT * FROM posts WHERE author_id = ''123'';\n-- Sẽ dùng Index Scan thay vì Sequential Scan\n```\n\n## Types of Indexes\n\n1. **B-tree Index** (default): Tốt cho comparison (=, <, >, BETWEEN)\n2. **Hash Index**: Tốt cho equality only\n3. **GiST, GIN**: Cho full-text search, array\n4. **BRIN**: Cho very large tables\n\n## Composite Indexes\n\nKhi query filter nhiều columns:\n\n```sql\nCREATE INDEX idx_posts_author_status ON posts(author_id, status);\n\n-- Query này sẽ dùng composite index\nSELECT * FROM posts WHERE author_id = ''123'' AND status = ''published'';\n```\n\n## Query Optimization Tips\n\n1. **Avoid SELECT * **: Lấy chỉ columns cần thiết\n2. **Use WHERE**: Filter sớm, giảm rows xử lý\n3. **JOIN optimization**: Có index trên join columns\n4. **LIMIT để pagination**: Không lấy tất cả rows cùng lúc\n\n```sql\n-- Tốt: Lấy 10 posts mới nhất của một tác giả\nSELECT id, title, created_at \nFROM posts \nWHERE author_id = ''123'' \nORDER BY created_at DESC \nLIMIT 10;\n```\n\n## Kiểm tra Index Efficiency\n\n```sql\nEXPLAIN (ANALYZE, BUFFERS)\nSELECT * FROM posts WHERE author_id = ''123'';\n```\n\nBuffers cho biết:\n- Heap Blks Read: Pages đọc từ disk\n- Heap Blks Hit: Pages đọc từ cache\n\nHit rate cao là tốt!\n\n## Kết luận\n\nTối ưu database:\n1. Dùng EXPLAIN ANALYZE để xác định bottleneck\n2. Tạo index trên columns thường xuyên được query\n3. Viết query hiệu quả (avoid SELECT *, use LIMIT)\n4. Monitor query performance định kỳ'
    ),
    (
      'N+1 Query Problem và cách giải quyết',
      'n-plus-1-query-problem-va-cach-giai-quyet',
      'Hiểu và khắc phục N+1 query problem trong ứng dụng web.',
      E'N+1 query problem là lỗi phổ biến gây hiệu năng kém. Nó xảy ra khi fetch 1 record, rồi lặp qua từng record mà mỗi lần fetch 1 query thêm.\n\n## Ví dụ N+1 Problem\n\nGiả sử có schema:\n- posts table\n- comments table (posts có many comments)\n\nCode sai:\n\n```javascript\n// Query 1: Lấy 10 posts\nconst posts = await db.query(\"SELECT * FROM posts LIMIT 10\");\n\n// Query 2-11: Lặp mỗi post, fetch comments\nfor (const post of posts) {\n  const comments = await db.query(\n    \"SELECT * FROM comments WHERE post_id = $1\", \n    [post.id]\n  );\n  post.comments = comments;\n}\n```\n\nKết quả: 1 + 10 = 11 queries!\n\n## Giải pháp 1: JOIN\n\n```sql\nSELECT \n  p.id, p.title, p.content,\n  c.id as comment_id, c.content as comment_content\nFROM posts p\nLEFT JOIN comments c ON c.post_id = p.id\nLIMIT 10;\n```\n\nChỉ 1 query, nhưng post data bị duplicate. Cần xử lý ở application layer.\n\n## Giải pháp 2: Eager Loading\n\nNếu dùng ORM (e.g., Sequelize, TypeORM):\n\n```javascript\n// TypeORM\nconst posts = await postRepository.find({\n  relations: [''comments''],\n  take: 10\n});\n\n// Sequelize\nconst posts = await Post.findAll({\n  include: [Comment],\n  limit: 10\n});\n```\n\nORM sẽ handle fetch efficiently (thường dùng JOIN hoặc separate queries + merge).\n\n## Giải pháp 3: Batch Loading\n\nFetch comments cho nhiều posts cùng lúc:\n\n```javascript\nconst posts = await db.query(\"SELECT * FROM posts LIMIT 10\");\nconst postIds = posts.map(p => p.id);\n\n// Fetch all comments một lần\nconst comments = await db.query(\n  \"SELECT * FROM comments WHERE post_id = ANY($1)\",\n  [postIds]\n);\n\n// Group comments by post_id\nconst commentsByPostId = {};\ncomments.forEach(c => {\n  if (!commentsByPostId[c.post_id]) {\n    commentsByPostId[c.post_id] = [];\n  }\n  commentsByPostId[c.post_id].push(c);\n});\n\n// Attach comments to posts\nposts.forEach(p => {\n  p.comments = commentsByPostId[p.id] || [];\n});\n```\n\n## Giải pháp 4: DataLoader (untuk GraphQL)\n\nDataLoader batch và cache queries:\n\n```javascript\nconst commentLoader = new DataLoader(async (postIds) => {\n  const comments = await db.query(\n    \"SELECT * FROM comments WHERE post_id = ANY($1)\",\n    [postIds]\n  );\n  \n  return postIds.map(id => \n    comments.filter(c => c.post_id === id)\n  );\n});\n\n// Dùng trong resolver\nconst resolvers = {\n  Post: {\n    comments: (post, _, { commentLoader }) => {\n      return commentLoader.load(post.id);\n    }\n  }\n};\n```\n\n## Best Practices\n\n1. Monitor queries: Dùng query logger để detect N+1\n2. Profiling: Xem query count và execution time\n3. Test: Viết test kiểm tra số lượng query\n4. Đánh giá trade-off: Memory vs Query count\n\nN+1 problem dễ xảy ra nhưng cách fix cũng không khó. Hãy proactive kiểm tra!'
    ),

    -- ========== API DESIGN ==========
    (
      'RESTful API Design: Best Practices',
      'restful-api-design-best-practices',
      'Những nguyên tắc thiết kế RESTful API tốt và cách implement.',
      E'RESTful API là chuẩn để xây dựng web services. Bài viết này chia sẻ best practices để design API sạch, dễ dùng và hiệu quả.\n\n## 1. Sử dụng đúng HTTP Methods\n\n```\nGET    /api/posts         - Lấy danh sách posts\nGET    /api/posts/:id     - Lấy chi tiết 1 post\nPOST   /api/posts         - Tạo post mới\nPUT    /api/posts/:id     - Update toàn bộ post\nPATCH  /api/posts/:id     - Update một phần post\nDELETE /api/posts/:id     - Xóa post\n```\n\n## 2. Status Codes chuẩn\n\n```\n200 OK              - Request thành công\n201 Created         - Resource mới được tạo\n204 No Content      - Request thành công, không có response body\n400 Bad Request     - Client error (invalid data)\n401 Unauthorized    - Chưa authenticate\n403 Forbidden       - Không có permission\n404 Not Found       - Resource không tồn tại\n500 Server Error    - Server error\n```\n\n## 3. API Versioning\n\nHãy version API để dễ maintain khi có breaking changes:\n\n```\n/api/v1/posts\n/api/v2/posts\n```\n\nHoặc dùng header:\n\n```\nGET /api/posts\nAPI-Version: 2\n```\n\n## 4. Filtering, Sorting, Pagination\n\n```\nGET /api/posts?status=published&sort=-created_at&limit=10&offset=0\n```\n\nThường dùng:\n- **limit/offset**: Simple pagination\n- **cursor**: Pagination dùng cursor (tốt hơn cho real-time data)\n- **sort**: Sort by field, prefix - cho descending\n- **filter**: Filter by any field\n\n## 5. Response Format\n\nResponse nên consistent:\n\n```json\n{\n  \"data\": {\n    \"id\": \"123\",\n    \"title\": \"My Post\",\n    \"content\": \"...\"\n  },\n  \"meta\": {\n    \"created_at\": \"2024-01-01T00:00:00Z\"\n  },\n  \"error\": null\n}\n```\n\nHoặc cho list:\n\n```json\n{\n  \"data\": [{...}, {...}],\n  \"pagination\": {\n    \"total\": 100,\n    \"limit\": 10,\n    \"offset\": 0\n  }\n}\n```\n\n## 6. Error Handling\n\nError response nên có:\n\n```json\n{\n  \"error\": {\n    \"code\": \"VALIDATION_ERROR\",\n    \"message\": \"Invalid input\",\n    \"details\": [\n      {\n        \"field\": \"email\",\n        \"message\": \"Invalid email format\"\n      }\n    ]\n  }\n}\n```\n\n## 7. HATEOAS (optional)\n\nInclude links trong response để client biết next actions:\n\n```json\n{\n  \"data\": {...},\n  \"links\": {\n    \"self\": \"/api/posts/123\",\n    \"update\": \"/api/posts/123\",\n    \"delete\": \"/api/posts/123\",\n    \"author\": \"/api/users/456\"\n  }\n}\n```\n\n## 8. Rate Limiting\n\nProtect API từ abuse:\n\n```\nX-RateLimit-Limit: 1000\nX-RateLimit-Remaining: 999\nX-RateLimit-Reset: 1672531200\n```\n\n## 9. Documentation\n\nUse OpenAPI/Swagger để document API:\n\n```yaml\nget:\n  /api/posts:\n    summary: Get all posts\n    parameters:\n      - name: status\n        in: query\n        schema:\n          type: string\n    responses:\n      200:\n        description: List of posts\n```\n\n## Checklist API Design\n\n✓ Sử dụng đúng HTTP methods\n✓ Consistent status codes\n✓ Clear error messages\n✓ Pagination cho large datasets\n✓ Proper authentication/authorization\n✓ Rate limiting\n✓ Good documentation\n✓ Versioning strategy\n\nAPI tốt là API dễ dùng và dễ maintain!'
    ),

    -- ========== WEB PERFORMANCE ==========
    (
      'Web Performance: Lazy Loading, Code Splitting, Compression',
      'web-performance-lazy-loading-code-splitting-compression',
      'Kỹ thuật tối ưu hiệu năng web: lazy loading, code splitting, gzip compression.',
      E'Web performance quan trọng cho SEO và user experience. Bài viết này hướng dẫn các kỹ thuật tối ưu hiệu năng web.\n\n## 1. Lazy Loading - Tải resource khi cần\n\n### Image Lazy Loading\n\n```html\n<img loading=\"lazy\" src=\"image.jpg\" alt=\"description\" />\n```\n\nHoặc dùng Intersection Observer API:\n\n```javascript\nconst observer = new IntersectionObserver((entries) => {\n  entries.forEach(entry => {\n    if (entry.isIntersecting) {\n      const img = entry.target;\n      img.src = img.dataset.src;\n      observer.unobserve(img);\n    }\n  });\n});\n\ndocument.querySelectorAll(''img[data-src]'').forEach(img => {\n  observer.observe(img);\n});\n```\n\n### Component Lazy Loading (React)\n\n```jsx\nconst HeavyComponent = React.lazy(() => import(''./HeavyComponent''));\n\nfunction App() {\n  return (\n    <Suspense fallback={<div>Loading...</div>}>\n      <HeavyComponent />\n    </Suspense>\n  );\n}\n```\n\n## 2. Code Splitting - Chia nhỏ bundle\n\nThay vì 1 file JavaScript lớn, chia thành nhiều chunks:\n\n### Route-based Code Splitting\n\n```jsx\nconst Home = React.lazy(() => import(''./pages/Home''));\nconst About = React.lazy(() => import(''./pages/About''));\nconst Contact = React.lazy(() => import(''./pages/Contact''));\n\nfunction App() {\n  return (\n    <Routes>\n      <Route path=\"/\" element={<Home />} />\n      <Route path=\"/about\" element={<About />} />\n      <Route path=\"/contact\" element={<Contact />} />\n    </Routes>\n  );\n}\n```\n\n### Bundler Config (Vite)\n\n```javascript\n// vite.config.ts\nexport default {\n  build: {\n    rollupOptions: {\n      output: {\n        manualChunks: {\n          ''vendor'': [''react'', ''react-dom''],\n          ''utils'': [''lodash'', ''date-fns'']\n        }\n      }\n    }\n  }\n};\n```\n\n## 3. Compression\n\n### Gzip Compression\n\nServer configuration (Nginx):\n\n```nginx\ngzip on;\ngzip_types text/plain text/css text/javascript application/json;\ngzip_min_length 1000;\ngzip_level 6;\n```\n\n### Next.js Compression\n\n```typescript\n// next.config.ts\nimport compression from ''compression'';\n\nexport default {\n  compress: true\n};\n```\n\n## 4. Caching Strategy\n\n### Browser Cache\n\n```\nCache-Control: public, max-age=31536000  # 1 year\nCache-Control: no-cache, must-revalidate # Always revalidate\n```\n\n### Service Worker\n\n```javascript\nself.addEventListener(''install'', event => {\n  event.waitUntil(\n    caches.open(''v1'').then(cache => {\n      return cache.addAll([\n        ''/'',\n        ''/style.css'',\n        ''/app.js''\n      ]);\n    })\n  );\n});\n\nself.addEventListener(''fetch'', event => {\n  event.respondWith(\n    caches.match(event.request).then(response => {\n      return response || fetch(event.request);\n    })\n  );\n});\n```\n\n## 5. Image Optimization\n\n### Responsive Images\n\n```html\n<picture>\n  <source srcset=\"image-small.jpg\" media=\"(max-width: 600px)\" />\n  <source srcset=\"image-large.jpg\" media=\"(min-width: 601px)\" />\n  <img src=\"image-large.jpg\" alt=\"description\" />\n</picture>\n```\n\n### Next.js Image Optimization\n\n```jsx\nimport Image from ''next/image'';\n\n<Image\n  src=\"/image.jpg\"\n  alt=\"description\"\n  width={800}\n  height={600}\n  priority\n/>\n```\n\n## 6. Metrics để đo\n\n- **LCP (Largest Contentful Paint)**: Khi element lớn nhất render\n- **FID (First Input Delay)**: Delay từ user input đến response\n- **CLS (Cumulative Layout Shift)**: Bao nhiêu layout shift\n\nTarget:\n- LCP < 2.5s\n- FID < 100ms\n- CLS < 0.1\n\nCheck bằng lighthouse hoặc WebPageTest.\n\n## Checklist Performance\n\n✓ Lazy load images và components\n✓ Code splitting theo route\n✓ Gzip compression\n✓ Browser caching strategy\n✓ Optimize images (size, format)\n✓ Monitor Web Vitals\n✓ Remove unused code\n✓ Minify CSS/JS\n\nPerformance improvement góp phần tuyệt vời vào SEO và user satisfaction!'
    ),

    -- ========== SECURITY ==========
    (
      'Web Security: CSRF, XSS, SQL Injection Prevention',
      'web-security-csrf-xss-sql-injection-prevention',
      'Các lỗ hổng web phổ biến và cách phòng chống: CSRF, XSS, SQL Injection.',
      E'Web security là vấn đề quan trọng. Bài viết này giới thiệu các lỗ hổng phổ biến và cách phòng chống.\n\n## 1. XSS (Cross-Site Scripting)\n\nXSS xảy ra khi attacker inject JavaScript code vào page.\n\n### Ví dụ XSS\n\n```html\n<!-- Nếu user input không được escape -->\n<div>{{ userComment }}</div>\n\n<!-- Attacker có thể submit: <img src=x onerror=\"alert(''hacked'')\"> -->\n<!-- Result: <img src=x onerror=\"alert(''hacked'')\"> được render -->\n```\n\n### Phòng chống XSS\n\n**React** (tự động escape):\n\n```jsx\n// React tự động escape\nreturn <div>{userComment}</div>; // Safe\n\n// Nếu cần render HTML, dùng DOMPurify\nimport DOMPurify from ''dompurify'';\nconst clean = DOMPurify.sanitize(userHTML);\nreturn <div dangerouslySetInnerHTML={{ __html: clean }} />;\n```\n\n**HTML Escape**:\n\n```javascript\nconst escapeHTML = (text) => {\n  const map = {\n    ''&'': ''&amp;'',\n    ''<'': ''&lt;'',\n    ''>'': ''&gt;'',\n    ''"'': ''&quot;'',\n    \"''\": ''&#039;''\n  };\n  return text.replace(/[&<>\"'']/g, m => map[m]);\n};\n```\n\n**Content Security Policy (CSP)**:\n\n```html\n<meta http-equiv=\"Content-Security-Policy\" \n      content=\"default-src ''self''; script-src ''self''; style-src ''self'' ''unsafe-inline''\" />\n```\n\n## 2. CSRF (Cross-Site Request Forgery)\n\nCSRF xảy ra khi attacker khiến user thực hiện action không muốn.\n\n### Ví dụ CSRF\n\n```html\n<!-- Attacker tạo page này -->\n<img src=\"https://bank.com/transfer?to=attacker&amount=1000\" />\n\n<!-- Nếu user đã login vào bank.com, request sẽ gửi với cookie -->\n```\n\n### Phòng chống CSRF\n\n**CSRF Token**:\n\n```javascript\n// Server: Tạo unique token cho mỗi session\nconst csrfToken = crypto.randomBytes(32).toString(''hex'');\nsession.csrfToken = csrfToken;\n\n// Client: Include token trong form\n<form method=\"POST\" action=\"/transfer\">\n  <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrfToken }}\" />\n  <input type=\"text\" name=\"amount\" />\n  <button type=\"submit\">Transfer</button>\n</form>\n\n// Server: Verify token\nif (req.body._csrf !== req.session.csrfToken) {\n  throw new Error(''CSRF token invalid'');\n}\n```\n\n**SameSite Cookie**:\n\n```javascript\nres.cookie(''session'', token, {\n  httpOnly: true,\n  secure: true,\n  sameSite: ''Strict'' // Prevent CSRF\n});\n```\n\n## 3. SQL Injection\n\nSQL Injection xảy ra khi user input được sử dụng trực tiếp trong SQL query.\n\n### Ví dụ SQL Injection\n\n```javascript\n// VULNERABLE - DON''T DO THIS\nconst query = `SELECT * FROM users WHERE email = ''${email}''`;\n\n// Attacker submit: admin@example.com'' OR ''1''=''1\n// Result: SELECT * FROM users WHERE email = ''admin@example.com'' OR ''1''=''1''\n// Return tất cả users!\n```\n\n### Phòng chống SQL Injection\n\n**Parameterized Queries**:\n\n```javascript\n// SAFE - Dùng parameterized query\nconst query = ''SELECT * FROM users WHERE email = $1'';\nconst result = await db.query(query, [email]);\n```\n\n**ORM**:\n\n```javascript\n// TypeORM - automatically parameterized\nconst user = await userRepository.findOne({\n  where: { email: email }\n});\n```\n\n## 4. Other Security Tips\n\n### Validate Input\n\n```javascript\nconst { body, validationResult } = require(''express-validator'');\n\napp.post(''/api/posts'', [\n  body(''title'').trim().isLength({ min: 1, max: 200 }),\n  body(''content'').trim().isLength({ min: 10 }),\n], (req, res) => {\n  const errors = validationResult(req);\n  if (!errors.isEmpty()) {\n    return res.status(400).json({ errors: errors.array() });\n  }\n});\n```\n\n### Use HTTPS\n\nLuôn sử dụng HTTPS để encrypt data in transit.\n\n### Secure Headers\n\n```javascript\nconst helmet = require(''helmet'');\napp.use(helmet());\n// Sets headers như: X-Frame-Options, X-Content-Type-Options, etc.\n```\n\n### Rate Limiting\n\n```javascript\nconst rateLimit = require(''express-rate-limit'');\n\nconst limiter = rateLimit({\n  windowMs: 15 * 60 * 1000, // 15 minutes\n  max: 100 // limit each IP to 100 requests per windowMs\n});\n\napp.use(''/api/'', limiter);\n```\n\n## Security Checklist\n\n✓ Escape user input (XSS prevention)\n✓ Use parameterized queries (SQL Injection prevention)\n✓ Implement CSRF tokens\n✓ Validate input server-side\n✓ Use HTTPS\n✓ Set secure headers (CSP, X-Frame-Options, etc)\n✓ Rate limiting\n✓ Keep dependencies updated\n✓ Don''t expose sensitive data in logs\n✓ Use httpOnly cookies for session tokens\n\nSecurity là process ongoing. Luôn update và monitor!'
    ),

    -- ========== TESTING ==========
    (
      'Unit Testing và Integration Testing trong JavaScript',
      'unit-testing-va-integration-testing-trong-javascript',
      'Cách viết unit tests và integration tests với Jest, Vitest, React Testing Library.',
      E'Testing là phần quan trọng của development. Bài viết này hướng dẫn cách viết unit tests và integration tests.\n\n## 1. Unit Testing - Test function độc lập\n\n### Setup Jest\n\n```bash\nnpm install --save-dev jest @testing-library/jest-dom\n```\n\n### Ví dụ Unit Test\n\n```javascript\n// math.js\nexport const add = (a, b) => a + b;\nexport const multiply = (a, b) => a * b;\n\n// math.test.js\ndescribe(''Math utilities'', () => {\n  test(''add function should return sum'', () => {\n    expect(add(2, 3)).toBe(5);\n    expect(add(-1, 1)).toBe(0);\n  });\n\n  test(''multiply function should return product'', () => {\n    expect(multiply(2, 3)).toBe(6);\n    expect(multiply(0, 100)).toBe(0);\n  });\n});\n```\n\n## 2. Testing React Components\n\n### React Testing Library\n\n```bash\nnpm install --save-dev @testing-library/react\n```\n\n### Ví dụ Component Test\n\n```javascript\n// Counter.jsx\nexport function Counter() {\n  const [count, setCount] = useState(0);\n  \n  return (\n    <div>\n      <p>Count: {count}</p>\n      <button onClick={() => setCount(count + 1)}>Increment</button>\n    </div>\n  );\n}\n\n// Counter.test.jsx\nimport { render, screen, fireEvent } from ''@testing-library/react'';\nimport { Counter } from ''./Counter'';\n\ndescribe(''Counter Component'', () => {\n  test(''should render initial count as 0'', () => {\n    render(<Counter />);\n    expect(screen.getByText(''Count: 0'')).toBeInTheDocument();\n  });\n\n  test(''should increment count when button clicked'', () => {\n    render(<Counter />);\n    const button = screen.getByRole(''button'', { name: /increment/i });\n    \n    fireEvent.click(button);\n    expect(screen.getByText(''Count: 1'')).toBeInTheDocument();\n    \n    fireEvent.click(button);\n    expect(screen.getByText(''Count: 2'')).toBeInTheDocument();\n  });\n});\n```\n\n## 3. Mocking Dependencies\n\n### Mock API Calls\n\n```javascript\n// userService.js\nexport const fetchUser = async (id) => {\n  const response = await fetch(`/api/users/${id}`);\n  return response.json();\n};\n\n// userService.test.js\nimport { fetchUser } from ''./userService'';\n\njest.mock(''node-fetch'', () => \n  jest.fn(() => \n    Promise.resolve({\n      json: () => Promise.resolve({ id: 1, name: ''John'' })\n    })\n  )\n);\n\ntest(''fetchUser should return user data'', async () => {\n  const user = await fetchUser(1);\n  expect(user.name).toBe(''John'');\n});\n```\n\n### Mock Function\n\n```javascript\nconst mockCallback = jest.fn();\nbutton.addEventListener(''click'', mockCallback);\n\nfireEvent.click(button);\n\nexpect(mockCallback).toHaveBeenCalled();\nexpect(mockCallback).toHaveBeenCalledTimes(1);\n```\n\n## 4. Integration Testing\n\nTest sự tương tác giữa nhiều components/services.\n\n```javascript\ndescribe(''User Registration Flow'', () => {\n  test(''complete registration flow'', async () => {\n    render(<RegisterForm />);\n    \n    // Fill form\n    fireEvent.change(screen.getByLabelText(/email/i), {\n      target: { value: ''test@example.com'' }\n    });\n    fireEvent.change(screen.getByLabelText(/password/i), {\n      target: { value: ''password123'' }\n    });\n    \n    // Submit\n    fireEvent.click(screen.getByRole(''button'', { name: /register/i }));\n    \n    // Assert\n    await waitFor(() => {\n      expect(screen.getByText(/registration successful/i)).toBeInTheDocument();\n    });\n  });\n});\n```\n\n## 5. Snapshot Testing\n\nSnapshot testing so sánh output hiện tại với baseline.\n\n```javascript\ntest(''renders correctly'', () => {\n  const { container } = render(<UserProfile user={user} />);\n  expect(container).toMatchSnapshot();\n});\n```\n\nLần đầu, tạo snapshot. Lần sau, so sánh output.\n\n## 6. Test Coverage\n\n```bash\nnpm run test -- --coverage\n```\n\nOutput:\n- Statements: % code được execute\n- Branches: % if/else branches tested\n- Functions: % functions called\n- Lines: % lines executed\n\nTarget: 80%+ coverage cho critical code.\n\n## Testing Best Practices\n\n✓ Test behavior, không implementation detail\n✓ Mỗi test test một điều\n✓ Clear test names\n✓ Setup/teardown khi cần\n✓ Isolate tests (không phụ thuộc thứ tự)\n✓ Mock external dependencies\n✓ Test edge cases\n✓ Maintain test code quality\n\n## Tool Recommendations\n\n- **Jest**: Unit testing framework\n- **React Testing Library**: Test React components\n- **Vitest**: Fast unit test (tương tự Jest)\n- **Playwright/Cypress**: E2E testing\n- **Mock Service Worker (MSW)**: Mock API responses\n\nGood tests = Confident refactoring!'
    ),

    -- ========== DEVOPS ==========
    (
      'Docker & Docker Compose cho development',
      'docker-and-docker-compose-cho-development',
      'Sử dụng Docker và Docker Compose để containerize ứng dụng.',
      E'Docker giúp đảm bảo consistency giữa development và production. Bài viết này hướng dẫn Docker & Docker Compose.\n\n## 1. Docker Basics\n\n### Dockerfile\n\n```dockerfile\nFROM node:18-alpine\n\nWORKDIR /app\n\nCOPY package*.json ./\nRUN npm ci\n\nCOPY . .\n\nEXPOSE 3000\n\nCMD [\"npm\", \"start\"]\n```\n\n### Build và Run\n\n```bash\n# Build image\ndocker build -t my-app:1.0 .\n\n# Run container\ndocker run -p 3000:3000 -e NODE_ENV=development my-app:1.0\n\n# View running containers\ndocker ps\n\n# View images\ndocker images\n```\n\n## 2. Docker Compose - Multiple Services\n\n### docker-compose.yml\n\n```yaml\nversion: ''3.8''\n\nservices:\n  app:\n    build: .\n    ports:\n      - ''3000:3000''\n    environment:\n      - NODE_ENV=development\n      - DATABASE_URL=postgresql://postgres:password@db:5432/myapp\n    depends_on:\n      - db\n    volumes:\n      - .:/app\n      - /app/node_modules\n\n  db:\n    image: postgres:15-alpine\n    environment:\n      - POSTGRES_USER=postgres\n      - POSTGRES_PASSWORD=password\n      - POSTGRES_DB=myapp\n    ports:\n      - ''5432:5432''\n    volumes:\n      - postgres_data:/var/lib/postgresql/data\n\n  redis:\n    image: redis:7-alpine\n    ports:\n      - ''6379:6379''\n\nvolumes:\n  postgres_data:\n```\n\n### Run Services\n\n```bash\n# Start all services\ndocker-compose up -d\n\n# View logs\ndocker-compose logs -f app\n\n# Stop services\ndocker-compose down\n\n# Remove volumes\ndocker-compose down -v\n```\n\n## 3. Development Workflow\n\n### Hot Reload\n\n```yaml\nservices:\n  app:\n    volumes:\n      - .:/app           # Mount current directory\n      - /app/node_modules  # Pero exclude node_modules\n    command: npm run dev  # Start dev server\n```\n\nBây giờ code changes sẽ tự động reload.\n\n## 4. Debugging\n\n### Node Inspector\n\n```dockerfile\nFROM node:18-alpine\n\nWORKDIR /app\nCOPY package*.json ./\nRUN npm ci\nCOPY . .\n\nEXPOSE 9229\nEXPOSE 3000\n\nCMD [\"node\", \"--inspect=0.0.0.0\", \"server.js\"]\n```\n\n```bash\n# Run\ndocker run -p 9229:9229 -p 3000:3000 my-app\n\n# Chrome DevTools: chrome://inspect\n```\n\n## 5. Multi-stage Build (Production)\n\n```dockerfile\n# Build stage\nFROM node:18-alpine AS builder\nWORKDIR /app\nCOPY package*.json ./\nRUN npm ci\nCOPY . .\nRUN npm run build\n\n# Production stage\nFROM node:18-alpine\nWORKDIR /app\nCOPY package*.json ./\nRUN npm ci --only=production\nCOPY --from=builder /app/dist ./dist\n\nEXPOSE 3000\nCMD [\"npm\", \"start\"]\n```\n\nImage size giảm vì chỉ copy necessary files.\n\n## 6. .dockerignore\n\n```\nnode_modules\nnpm-debug.log\n.git\n.gitignore\n.env\n.DS_Store\ndist\nbuild\n```\n\n## 7. Environment Variables\n\n### .env file\n\n```\nDATABASE_URL=postgresql://postgres:password@db:5432/myapp\nNODE_ENV=development\nAPI_KEY=your-api-key\n```\n\n### docker-compose.yml\n\n```yaml\nservices:\n  app:\n    env_file: .env\n    environment:\n      - CUSTOM_VAR=value\n```\n\n## Best Practices\n\n✓ Use .dockerignore để reduce image size\n✓ Use Alpine images (nhỏ hơn)\n✓ Multi-stage builds cho production\n✓ Don''t run as root\n✓ Pin versions (node:18 thay vì node:latest)\n✓ Health checks\n✓ Logging tới stdout\n✓ Keep layers small\n\n## Useful Commands\n\n```bash\n# Execute command inside running container\ndocker-compose exec app npm run test\n\n# View container filesystem\ndocker exec app ls -la\n\n# Clean up unused resources\ndocker system prune\n\n# View container resource usage\ndocker stats\n```\n\nDocker làm development environment consistent và predictable!'
    )
)
insert into public.posts (author_id, title, slug, excerpt, content, status, published_at)
select
  a.id as author_id,
  s.title,
  s.slug,
  s.excerpt,
  s.content,
  'published'::public.post_status,
  now()
from seed_posts s
cross join author_profile a
on conflict (slug)
do update set
  title = excluded.title,
  excerpt = excluded.excerpt,
  content = excluded.content,
  status = excluded.status,
  published_at = excluded.published_at,
  updated_at = now();

-- Verify result
select
  count(*) as total_posts,
  count(case when status = 'published' then 1 end) as published,
  count(case when status = 'draft' then 1 end) as draft
from public.posts;

-- Show all inserted topics
select distinct
  case
    when title ilike '%React%' then 'React'
    when title ilike '%TypeScript%' then 'TypeScript'
    when title ilike '%PostgreSQL%' or title ilike '%database%' then 'Database'
    when title ilike '%N+1%' then 'Database'
    when title ilike '%REST%' or title ilike '%API%' then 'API Design'
    when title ilike '%Performance%' or title ilike '%Lazy%' or title ilike '%Code%' then 'Web Performance'
    when title ilike '%Security%' or title ilike '%CSRF%' or title ilike '%XSS%' or title ilike '%SQL%' then 'Web Security'
    when title ilike '%Test%' then 'Testing'
    when title ilike '%Docker%' then 'DevOps'
    else 'Other'
  end as topic
from public.posts
where status = 'published'::public.post_status
order by 1;
